CREATE TYPE "TripStatus" AS ENUM ('PLANNED','ASSIGNED','IN_TRANSIT','STOPPED','PAUSED_LUNCH','INCIDENT','ARRIVED','RETURNED','CANCELLED');
CREATE TYPE "AssignmentStatus" AS ENUM ('ACTIVE','REVOKED');
CREATE TYPE "LegExecutionStatus" AS ENUM ('NOT_STARTED','RUNNING','PAUSED','FINISHED');
CREATE TYPE "OperationEventType" AS ENUM ('STARTED','STOPPED','LUNCH_STARTED','LUNCH_ENDED','INCIDENT','INCIDENT_RESOLVED','ARRIVED','RETURNED','CANCELLED');
CREATE TABLE "trips" ("id" SERIAL PRIMARY KEY,"code" VARCHAR(32) NOT NULL UNIQUE,"origin" VARCHAR(160) NOT NULL,"timezone" VARCHAR(64) NOT NULL DEFAULT 'America/Bogota',"initial_start_at" TIMESTAMP(3) NOT NULL,"notes" VARCHAR(1000),"status" "TripStatus" NOT NULL DEFAULT 'PLANNED',"created_by_id" INTEGER NOT NULL,"cancelled_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "trip_legs" ("id" SERIAL PRIMARY KEY,"trip_id" INTEGER NOT NULL,"sequence" INTEGER NOT NULL,"origin" VARCHAR(160) NOT NULL,"destination" VARCHAR(160) NOT NULL,"planned_departure_at" TIMESTAMP(3) NOT NULL,"duration_days" INTEGER NOT NULL,"planned_arrival_at" TIMESTAMP(3) NOT NULL,"notes" VARCHAR(1000));
CREATE TABLE "trip_assignments" ("id" SERIAL PRIMARY KEY,"trip_id" INTEGER NOT NULL,"leg_id" INTEGER,"bus_id" INTEGER NOT NULL,"driver_id" INTEGER NOT NULL,"status" "AssignmentStatus" NOT NULL DEFAULT 'ACTIVE',"assigned_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"revoked_at" TIMESTAMP(3));
CREATE TABLE "leg_executions" ("id" SERIAL PRIMARY KEY,"leg_id" INTEGER NOT NULL UNIQUE,"status" "LegExecutionStatus" NOT NULL DEFAULT 'NOT_STARTED',"actual_departure_at" TIMESTAMP(3),"actual_arrival_at" TIMESTAMP(3));
CREATE TABLE "operation_events" ("id" SERIAL PRIMARY KEY,"trip_id" INTEGER NOT NULL,"execution_id" INTEGER,"type" "OperationEventType" NOT NULL,"occurred_at" TIMESTAMP(3) NOT NULL,"resumed_at" TIMESTAMP(3),"notes" VARCHAR(1000),"metadata" JSONB,"actor_id" INTEGER NOT NULL);
ALTER TABLE "trips" ADD CONSTRAINT "trips_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id");
ALTER TABLE "trip_legs" ADD CONSTRAINT "trip_legs_trip_id_fkey" FOREIGN KEY ("trip_id") REFERENCES "trips"("id");
ALTER TABLE "trip_assignments" ADD CONSTRAINT "trip_assignments_trip_id_fkey" FOREIGN KEY ("trip_id") REFERENCES "trips"("id"), ADD CONSTRAINT "trip_assignments_leg_id_fkey" FOREIGN KEY ("leg_id") REFERENCES "trip_legs"("id"), ADD CONSTRAINT "trip_assignments_bus_id_fkey" FOREIGN KEY ("bus_id") REFERENCES "buses"("id"), ADD CONSTRAINT "trip_assignments_driver_id_fkey" FOREIGN KEY ("driver_id") REFERENCES "users"("id");
ALTER TABLE "leg_executions" ADD CONSTRAINT "leg_executions_leg_id_fkey" FOREIGN KEY ("leg_id") REFERENCES "trip_legs"("id");
ALTER TABLE "operation_events" ADD CONSTRAINT "operation_events_trip_id_fkey" FOREIGN KEY ("trip_id") REFERENCES "trips"("id"), ADD CONSTRAINT "operation_events_execution_id_fkey" FOREIGN KEY ("execution_id") REFERENCES "leg_executions"("id"), ADD CONSTRAINT "operation_events_actor_id_fkey" FOREIGN KEY ("actor_id") REFERENCES "users"("id");
CREATE UNIQUE INDEX "trip_legs_trip_id_sequence_key" ON "trip_legs"("trip_id","sequence");
CREATE INDEX "trips_status_initial_start_at_idx" ON "trips"("status","initial_start_at");
CREATE INDEX "trip_legs_trip_id_planned_departure_at_idx" ON "trip_legs"("trip_id","planned_departure_at");
CREATE INDEX "trip_assignments_bus_id_status_assigned_at_idx" ON "trip_assignments"("bus_id","status","assigned_at");
CREATE INDEX "trip_assignments_driver_id_status_assigned_at_idx" ON "trip_assignments"("driver_id","status","assigned_at");
CREATE INDEX "operation_events_trip_id_occurred_at_idx" ON "operation_events"("trip_id","occurred_at");
ALTER TABLE "trip_legs" ADD CONSTRAINT "trip_legs_duration_days_check" CHECK ("duration_days" >= 1);
